1	export type Card = {
2	  monster: string;
3	  rank?: number;
4	};
5	
6	const SPHINX = "sphinx";
7	
8	const isSphinx = (card: Card): boolean => card.monster === SPHINX;
9	
10	// A card's type is its monster name alone: rank distinguishes cards, not types,
11	// so Undead Warrior ranks 1 and 3 are two cards of a single type.
12	const monsterTypeOf = (card: Card): string => card.monster;
13	
14	const countDistinctMonsterTypes = (army: Card[]): number =>
15	  new Set(army.map(monsterTypeOf)).size;
16	
17	const SCORE_WITHOUT_ENOUGH_VARIETY = 2;
18	
19	// Ordered from the most demanding requirement down, so the first entry whose
20	// requirement is satisfied is also the highest-scoring one available.
21	const SCORE_TIERS: ReadonlyArray<{
22	  atLeastTypes: number;
23	  score: number;
24	}> = [
25	  { atLeastTypes: 6, score: 5 },
26	  { atLeastTypes: 4, score: 3 },
27	];
28	
29	const scorePerSphinxForVariety = (distinctTypes: number): number =>
30	  SCORE_TIERS.find(({ atLeastTypes }) => distinctTypes >= atLeastTypes)?.score ??
31	  SCORE_WITHOUT_ENOUGH_VARIETY;
32	
33	const countSphinxes = (army: Card[]): number => army.filter(isSphinx).length;
34	
35	export const scoreArmy = (army: Card[]): number =>
36	  countSphinxes(army) *
37	  scorePerSphinxForVariety(countDistinctMonsterTypes(army));
38

